-- Rows a new installation needs, as the Python app's first request writes them
-- (app.py _seed_all_data: Role.seed, the role permissions, GlobalLimits.get) and
-- the Alembic revision this schema is at, so the Python app from the backup reads
-- a database the .NET migrator built. Generated by dotnet/tools/make_migration_fixtures.py.

SELECT pg_catalog.setval('public.roles_id_seq', (SELECT max(id) FROM public.roles), true);

SELECT pg_catalog.setval('public.permissions_id_seq', (SELECT max(id) FROM public.permissions), true);

SELECT pg_catalog.setval('public.global_limits_id_seq', 1, true);

